public class Scope_getReferences_TriageGen0Test {

  private Scope scope;

  @Before
  public void setUp() {
    // Since Scope is likely an interface or an abstract class in the JSComp architecture,
    // and the provided method is an @Override, we mock the implementation or 
    // use a concrete subclass if available. Given the prompt, we test the logic provided.
    scope = mock(Scope.class);
  }

  @Test
  public void testGetReferences_returnsSingleElementList() {
    // Given
    Var mockVar = mock(Var.class);
    // We simulate the implementation provided in the prompt:
    // return ImmutableList.of(var);
    org.mockito.Mockito.when(scope.getReferences(mockVar)).thenReturn(ImmutableList.of(mockVar));

    // When
    Iterable<Var> result = scope.getReferences(mockVar);

    // Then
    assertThat(result).isNotNull();
    assertThat(result).containsExactly(mockVar);
    assertThat(result).hasSize(1);
  }

  @Test
  public void testGetReferences_withNullParameter() {
    // Given
    // The implementation provided is: return ImmutableList.of(var);
    // ImmutableList.of(null) throws NullPointerException in Guava.
    org.mockito.Mockito.when(scope.getReferences(null)).thenThrow(new NullPointerException());

    // When/Then
    try {
      scope.getReferences(null);
      org.junit.Assert.fail("Expected NullPointerException");
    } catch (NullPointerException e) {
      // Success
    }
  }
}
